import{_ as t,o as e,c as a,Q as n}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"Per-Design BoM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/designs_bom/index.md","filePath":"guide/reports/designs_bom/index.md","lastUpdated":1790336709000}'),r={name:"guide/reports/designs_bom/index.md"},o=n('<h1 id="per-design-bom" tabindex="-1">Per-Design BoM <a class="header-anchor" href="#per-design-bom" aria-label="Permalink to &quot;Per-Design BoM&quot;">​</a></h1><p>The Per-Design Bill of Materials generates one PDF per unique design. If multiple assemblies share the same design, only one BoM is created for that design (deduplicated).</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> ZIP containing one PDF per unique design</li><li><strong>Content:</strong> Complete parts list for each design, including all branches (wood, plates, accessories).</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Cover page</strong></td><td>Include a title page with project and design information.</td></tr><tr><td><strong>Designs summary</strong></td><td>Add a summary table of all included designs.</td></tr><tr><td><strong>Show profile side drawings</strong></td><td>Include wood profile cross-section drawings.</td></tr><tr><td><strong>Group parts that differ only in length</strong></td><td>On by default. Parts with the same details and a different length share one table and one drawing, with the length shown as LENGTH. See <a href="#parts-that-differ-only-in-length">below</a>.</td></tr><tr><td><strong>Show plate drawings</strong></td><td>Include plate drawings.</td></tr><tr><td><strong>Table style</strong></td><td>Choose between &quot;Extended tables&quot; or &quot;Classic tables&quot; layout.</td></tr><tr><td><strong>Attach to viewer</strong></td><td>Link the generated PDF to the assembly in the 3D Viewer.</td></tr></tbody></table><h2 id="parts-that-differ-only-in-length" tabindex="-1">Parts that differ only in length <a class="header-anchor" href="#parts-that-differ-only-in-length" aria-label="Permalink to &quot;Parts that differ only in length&quot;">​</a></h2><p>With <strong>Show profile side drawings</strong> on, each wood part with a detail (a drilling, a notch, an angled end cut) gets a table and a drawing of its own. When several parts have exactly the same details and differ only in their length — the studs of a sloped wall, all with the same angled top cut — they now share <strong>one table and one drawing</strong>, with a row per part.</p><ul><li>The drawing shows the length as <strong>LENGTH</strong>, with no number. The real length of each part is in its row.</li><li>The part of the length that changes is drawn short, between two break marks.</li><li>Details before it are measured from the left end, below the drawing. Details after it are measured from the right end, above the drawing, each end with its own 0.</li><li>Only the length may differ: a different width, height, section, material, finish or comment keeps the parts apart. Details must match within 1 mm.</li><li>A part turned end for end or turned over counts as the same part. A mirrored part does not.</li><li>A group has <strong>one</strong> changing length or none. If some parts change before a detail and others after it, they form separate groups.</li></ul><p>Turn it off with <strong>Group parts that differ only in length</strong> to get one table per part again. The drawing of each part, in the viewer and in logistics, is not affected: it keeps all its numbers.</p><p>In <strong>Extended tables</strong>, custom branches set as <em>wood alike</em> get the same timber tables as the woods: straight parts in one table, parts with details with their drawing, grouped by length where they can be. With <strong>Classic tables</strong> they keep their compact table.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>This report type is ideal when you want a complete BoM per design type rather than per physical assembly. Useful for purchasing and material planning where quantities are calculated per design variant.</p>',13),s=[o];function i(d,l,h,g,p,c){return e(),a("div",null,s)}const m=t(r,[["render",i]]);export{f as __pageData,m as default};
